//! Explicit codec/worker failures remain separate checked Result alternatives.
use super::*;
use crate::native_signatures::NativeTypeId;
impl Emitter<'_>{
 pub(super) fn compression_record(&self,id:usize,fields:Vec<String>)->String{let fields=fields.into_iter().enumerate().map(|(index,value)|format!("field{index}:{value}")).collect::<Vec<_>>().join(",");format!("Record{}{{{fields}{}}}",self.native_record_declaration(id),self.schema_record_order(id))}
 pub(super) fn compression_code(&self,ty:Type,value:&str)->String{let Type::Union(id)=ty else{unreachable!("finite codec error code")};let arms=self.program.unions[id.index()].members.iter().enumerate().map(|(tag,member)|{let Type::Literal(record,_)=member else{unreachable!()};let crate::literal_types::LiteralValue::String(code)=self.program.records[*record].literal_definition.as_ref().unwrap()else{unreachable!()};let payload=self.union_store_payload(id,*member,&format!("String::Borrowed({code:?})"));format!("{code:?}=>Union{}::V{tag}({payload})",id.index())}).collect::<Vec<_>>().join(",");format!("match {value}{{{arms},_=>unreachable!(\"checked codec error code\")}}")}
 fn compression_result(&self,ty:Type,call:&str)->String{
  let Type::Union(id)=ty else{unreachable!("codec Result")};let members=&self.program.unions[id.index()].members;let[ok,err]=crate::result_identity::variants(&self.program.records,members).unwrap();let tag=|record|members.iter().position(|ty|*ty==Type::Record(record)).unwrap();let failure=self.program.records[err].fields[0].ty.unwrap();let Type::Union(errors)=failure else{unreachable!("codec typed failure union")};let record=|identity|self.program.unions[errors.index()].members.iter().find_map(|ty|if let Type::Record(record)=ty{(self.program.records[*record].native_type==Some(identity)).then_some(*record)}else{None}).unwrap();let codec=record(NativeTypeId::CompressionError);let admission=record(NativeTypeId::SpawnError);let completion=record(NativeTypeId::ThreadError);
  let failed=|record,fields|self.compression_record(err,vec![self.future_inject(Type::Record(record),failure,&self.compression_record(record,fields))]);
  let codec_error=failed(codec,vec![self.compression_code(self.program.records[codec].fields[0].ty.unwrap(),"error.code"),"String::Borrowed(error.operation)".into(),"String::Owned(error.message)".into()]);
  let admission_error=failed(admission,vec!["String::Borrowed(error.code)".into(),"String::Owned(error.to_string())".into()]);
  let panic=failed(completion,vec!["String::Borrowed(\"panic\")".into(),"TsrUndefined".into()]);let cancelled=failed(completion,vec!["String::Borrowed(\"cancelled\")".into(),"TsrUndefined".into()]);
  let Type::Record(bytes)=self.program.records[ok].fields[0].ty.unwrap()else{unreachable!()};let success=self.compression_record(ok,vec![format!("Record{}{{bytes:value}}",self.native_record_declaration(bytes))]);
  format!("match {call}{{Ok(value)=>Union{}::V{}({success}),Err(error)=>Union{}::V{}(match error{{tsrust_native_compression::Failure::Codec(error)=>{codec_error},tsrust_native_compression::Failure::Admission(error)=>{admission_error},tsrust_native_compression::Failure::Completion(tsrust_native_threads::JoinError::Panic)=>{panic},tsrust_native_compression::Failure::Completion(tsrust_native_threads::JoinError::Cancelled)=>{cancelled},tsrust_native_compression::Failure::Completion(tsrust_native_threads::JoinError::Worker(never))=>match never{{}}}})}}",id.index(),tag(ok),id.index(),tag(err))
 }
 pub(super) fn compression_native(&self,fun:&CheckedFunction,expr:&Expr,id:usize,args:&[Expr])->Option<String>{let binding=&crate::native_bindings::BINDINGS[id];if binding.module!="std:compression"{return None;}if let Some(call)=self.compression_stream_native(fun,expr,id,args){return Some(call);}self.native_bindings.borrow_mut().insert(id);let name=binding.name.trim_start_matches('_');let values=args.iter().zip(binding.parameters).map(|(arg,parameter)|self.expr(fun,arg,parameter.access)).collect::<Vec<_>>();
  let option=if let Some(argument)=args.get(2){let optional=self.native_optional_argument(&binding.parameters[2],"compression_options".into(),argument.ty.unwrap());let record=match argument.ty.unwrap(){Type::Record(record)=>Some(record),Type::Union(union)=>self.program.unions[union.index()].members.iter().find_map(|ty|if let Type::Record(record)=ty{Some(*record)}else{None}),_=>None};if let Some(record)=record{let Type::Union(union)=self.program.records[record].fields[0].ty.unwrap()else{unreachable!()};let arms=self.program.unions[union.index()].members.iter().enumerate().map(|(tag,member)|format!("Union{}::V{tag}(value)=>{}",union.index(),if *member==Type::Undefined{"None"}else{"Some(value)"})).collect::<Vec<_>>().join(",");format!("({optional}).and_then(|options|match options.field0{{{arms}}})")}else{format!("{{let _={optional};None}}")}}else{"None".into()};
  let format=match name{"gzip"|"gunzip"=>"Gzip","deflate"|"inflate"=>"Zlib","deflateRaw"|"inflateRaw"=>"Raw",_=>unreachable!("registered codec operation")};let direction=if matches!(name,"gunzip"|"inflate"|"inflateRaw"){"Decode"}else{"Encode"};let setup=if args.len()>2{format!("let compression_options={};",values[2])}else{String::new()};let call=format!("{{let compression_pool={};let compression_input={};{setup}let compression_option={option};tsrust_native_compression::run(compression_pool,compression_input.bytes,tsrust_native_compression::Format::{format},tsrust_native_compression::Direction::{direction},compression_option,{name:?}).await}}",values[0],values[1]);Some(self.compression_result(expr.ty.unwrap(),&call))
 }
}
